#[cfg(test)]
mod tests {
    use std::{
        panic::{catch_unwind, AssertUnwindSafe},
        sync::{Arc, Mutex, OnceLock},
    };

    use super::{DeclarationEvent, DeclarationKind, DeclarationsListenerState};
    use crate::{api::handlers::Callback, key_expr::KeyExpr};

    fn subscriber(key_expr: &str) -> DeclarationEvent {
        DeclarationEvent {
            kind: DeclarationKind::Subscriber,
            id: 0,
            key_expr: KeyExpr::try_from(key_expr.to_string()).unwrap(),
            declared: true,
        }
    }

    fn heard(log: &Mutex<Vec<String>>) -> Vec<String> {
        log.lock().unwrap().clone()
    }

    #[test]
    fn drain_delivers_the_current_events_then_the_pushed_ones_in_order() {
        let log = Arc::new(Mutex::new(Vec::new()));
        let sink = log.clone();
        let state = DeclarationsListenerState::new(
            0,
            Callback::from(move |event: DeclarationEvent| {
                sink.lock().unwrap().push(event.key_expr().to_string())
            }),
            vec![subscriber("a/1"), subscriber("a/2")],
        );
        state.push(subscriber("a/3"));
        state.drain();
        state.push(subscriber("a/4"));
        state.drain();
        assert_eq!(heard(&log), ["a/1", "a/2", "a/3", "a/4"]);
    }

    #[test]
    fn a_drain_inside_a_callback_leaves_its_events_to_the_drain_delivering() {
        let log = Arc::new(Mutex::new(Vec::new()));
        let sink = log.clone();
        let this: Arc<OnceLock<Arc<DeclarationsListenerState>>> = Arc::new(OnceLock::new());
        let inner = this.clone();
        let state = DeclarationsListenerState::new(
            0,
            Callback::from(move |event: DeclarationEvent| {
                let key_expr = event.key_expr().to_string();
                sink.lock().unwrap().push(key_expr.clone());
                if key_expr == "a/1" {
                    let state = inner.get().unwrap();
                    state.push(subscriber("a/2"));
                    state.drain();
                    sink.lock().unwrap().push("a/1 returned".to_string());
                }
            }),
            vec![subscriber("a/1")],
        );
        this.set(state.clone()).unwrap();
        state.drain();
        assert_eq!(heard(&log), ["a/1", "a/1 returned", "a/2"]);
    }

    #[test]
    fn after_a_callback_panics_the_next_drain_delivers_the_rest() {
        let log = Arc::new(Mutex::new(Vec::new()));
        let sink = log.clone();
        let state = DeclarationsListenerState::new(
            0,
            Callback::from(move |event: DeclarationEvent| {
                let key_expr = event.key_expr().to_string();
                if key_expr == "a/1" {
                    panic!("the callback panics on {key_expr}");
                }
                sink.lock().unwrap().push(key_expr);
            }),
            vec![subscriber("a/1"), subscriber("a/2")],
        );
        assert!(catch_unwind(AssertUnwindSafe(|| state.drain())).is_err());
        state.push(subscriber("a/3"));
        state.drain();
        assert_eq!(heard(&log), ["a/2", "a/3"]);
    }
}
